"""Generic layout utility functions with no dataset-specific logic."""

from typing import Dict, List, Tuple

import numpy as np
import torch


FEATURE_DIM = 35


def rotate_layout_features_for_augmentation(chunk, map_features, k, rotation_direction="cw"):
    """Rotate vectorized layout features to match 90-degree chunk augmentation.

    Args:
        chunk: Augmented chunk tensor with spatial layout [..., X, Z, Y].
        map_features: Vectorized layout features in the same local coordinate frame.
        k: Number of 90-degree rotations used by torch.rot90.
        rotation_direction: Direction implied by the dataset's chosen rot90 dims.
            - "cw": positive k rotates the topdown plane clockwise
            - "ccw": positive k rotates the topdown plane counter-clockwise
    """
    # Chunk spatial layout is always [..., X, Z, Y]; ignore any leading channel dim.
    size_x = chunk.shape[-3]
    size_y = chunk.shape[-1]

    old_x = map_features[:, 0].copy()
    old_y = map_features[:, 2].copy()

    if rotation_direction not in {"cw", "ccw"}:
        raise ValueError(f"Unsupported rotation_direction: {rotation_direction}")

    if rotation_direction == "cw":
        if k == 1:
            map_features[:, 0] = old_y
            map_features[:, 2] = (size_x - 1) - old_x
        elif k == 2:
            map_features[:, 0] = (size_x - 1) - old_x
            map_features[:, 2] = (size_y - 1) - old_y
        elif k == 3:
            map_features[:, 0] = (size_y - 1) - old_y
            map_features[:, 2] = old_x
    else:
        if k == 1:
            map_features[:, 0] = (size_y - 1) - old_y
            map_features[:, 2] = old_x
        elif k == 2:
            map_features[:, 0] = (size_x - 1) - old_x
            map_features[:, 2] = (size_y - 1) - old_y
        elif k == 3:
            map_features[:, 0] = old_y
            map_features[:, 2] = (size_x - 1) - old_x

    is_oriented_box = map_features[:, 8] > 0.5
    if is_oriented_box.any():
        angle_sign = -1.0 if rotation_direction == "cw" else 1.0
        angle = angle_sign * k * np.pi / 2
        cos_h = map_features[is_oriented_box, 6]
        sin_h = map_features[is_oriented_box, 7]
        new_cos = np.cos(angle) * cos_h - np.sin(angle) * sin_h
        new_sin = np.sin(angle) * cos_h + np.cos(angle) * sin_h
        map_features[is_oriented_box, 6] = new_cos
        map_features[is_oriented_box, 7] = new_sin
    return map_features


def flip_layout_features_for_augmentation(chunk, map_features, flip_dim):
    """Flip vectorized layout features to match a horizontal chunk flip.

    Chunk spatial layout is [..., X, Z, Y]. Valid flip dims are the actual tensor
    dims used by the dataset augmentation code, e.g. 0/2 for [X,Z,Y] tensors or
    1/3 for [C,X,Z,Y] tensors.
    """
    size_x = chunk.shape[-3]
    size_y = chunk.shape[-1]

    if flip_dim in {0, 1, -3}:
        map_features[:, 0] = (size_x - 1) - map_features[:, 0]
        is_oriented_box = map_features[:, 8] > 0.5
        if is_oriented_box.any():
            map_features[is_oriented_box, 6] = -map_features[is_oriented_box, 6]
    elif flip_dim in {2, 3, -1}:
        map_features[:, 2] = (size_y - 1) - map_features[:, 2]
        is_oriented_box = map_features[:, 8] > 0.5
        if is_oriented_box.any():
            map_features[is_oriented_box, 7] = -map_features[is_oriented_box, 7]
    else:
        raise ValueError(f"Unsupported flip_dim for layout augmentation: {flip_dim}")

    return map_features


def rasterize_polylines(
    polylines: List[torch.Tensor],
    volume_shape: Tuple[int, int, int],
    device: str = "cpu",
) -> torch.Tensor:
    """Rasterize 3D polylines into a voxel grid."""
    if not polylines:
        return torch.zeros(volume_shape, dtype=torch.float32, device=device)

    X, Z, Y = volume_shape
    all_points = []
    for pts in polylines:
        if pts.device != torch.device(device):
            pts = pts.to(device)
        all_points.append(pts)
        all_points.append(torch.full((1, 3), float("nan"), dtype=torch.float32, device=device))

    pts = torch.cat(all_points, dim=0)
    valid = ~torch.isnan(pts[:, 0])
    mask = valid[:-1] & valid[1:]
    p1 = pts[:-1][mask]
    p2 = pts[1:][mask]

    if p1.shape[0] == 0:
        return torch.zeros(volume_shape, dtype=torch.float32, device=device)

    delta = p2 - p1
    max_delta = torch.max(torch.abs(delta), dim=1).values
    num_steps = torch.ceil(max_delta).int() + 1
    max_steps = int(num_steps.max().item())

    t = torch.linspace(0, 1, max_steps, device=device)
    interp = p1[:, None, :] + delta[:, None, :] * t[None, :, None]
    vox = torch.round(interp).long()

    mask = (
        (vox[..., 0] >= 0)
        & (vox[..., 0] < X)
        & (vox[..., 1] >= 0)
        & (vox[..., 1] < Z)
        & (vox[..., 2] >= 0)
        & (vox[..., 2] < Y)
    )
    vox = vox[mask]

    grid = torch.zeros((X, Z, Y), dtype=torch.float32, device=device)
    if vox.numel() > 0:
        grid.index_put_(
            (vox[:, 0], vox[:, 1], vox[:, 2]),
            torch.ones(vox.shape[0], dtype=torch.float32, device=device),
            accumulate=True,
        )

    return grid > 0


def rasterize_oriented_boxes(
    boxes: List[Dict],
    volume_shape: Tuple[int, int, int],
    voxel_size: float = 0.1,
    device: str = "cpu",
) -> torch.Tensor:
    """Rasterize 3D oriented boxes as solid occupied voxels."""
    if not boxes:
        return torch.zeros(volume_shape, dtype=torch.float32, device=device)

    X, Z, Y = volume_shape
    grid = torch.zeros((X, Z, Y), dtype=torch.float32, device=device)

    for box in boxes:
        if isinstance(box["center"], torch.Tensor):
            center = box["center"].to(device=device, dtype=torch.float32)
        else:
            center = torch.tensor(box["center"], dtype=torch.float32, device=device)

        heading = box["heading"]
        length = box["length"] / voxel_size
        width = box["width"] / voxel_size
        height = box["height"] / voxel_size

        cos_h = torch.cos(torch.tensor(heading, device=device)).item()
        sin_h = torch.sin(torch.tensor(heading, device=device)).item()
        hl, hw, hh = length / 2, width / 2, height / 2

        x_min = int(max(0, center[0].item() - max(hw, hl)))
        x_max = int(min(X, center[0].item() + max(hw, hl) + 1))
        z_min = int(max(0, center[1].item() - hh))
        z_max = int(min(Z, center[1].item() + hh + 1))
        y_min = int(max(0, center[2].item() - max(hw, hl)))
        y_max = int(min(Y, center[2].item() + max(hw, hl) + 1))

        if x_max <= x_min or z_max <= z_min or y_max <= y_min:
            continue

        x_coords = torch.arange(x_min, x_max, device=device)
        z_coords = torch.arange(z_min, z_max, device=device)
        y_coords = torch.arange(y_min, y_max, device=device)
        xx, zz, yy = torch.meshgrid(x_coords, z_coords, y_coords, indexing="ij")

        dx = xx - center[0]
        dy = yy - center[2]
        dz = zz - center[1]

        local_x = dx * cos_h + dy * sin_h
        local_y = -dx * sin_h + dy * cos_h

        mask = (
            (torch.abs(local_x) <= hl)
            & (torch.abs(local_y) <= hw)
            & (torch.abs(dz) <= hh)
        )

        grid[xx[mask], zz[mask], yy[mask]] = 1

    return grid
